WITH RECURSIVE cascades(oid) AS (
 SELECT oid FROM pg_class WHERE oid IN('auth.users'::regclass,'public.etablissements'::regclass)
 UNION SELECT k.conrelid FROM pg_constraint k JOIN cascades c ON k.confrelid=c.oid WHERE k.contype='f' AND k.confdeltype IN('c','n','d')
), fixture AS (SELECT ARRAY(SELECT ('99011000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid FROM generate_series(1,7) n) AS ids),
tables_cibles(nom) AS (VALUES ('auth.users'),('private.security_definer_inventory'),('private.suppression_etablissement_context'),('private.suppressions_compte_confirmees'),('public.admins_groupe_sante'),('public.api_keys'),('public.calendar_connections'),('public.calendar_events_sync'),('public.contrats_mission'),('public.contrats_service_signatures'),('public.email_queue'),('public.etablissements'),('public.evaluations'),('public.exclusions'),('public.journaux_audit'),('public.membres_etablissement'),('public.messages_chat'),('public.messages_litige'),('public.messages_mission'),('public.notations_missions'),('public.notifications'),('public.partages_rib'),('public.preferences_notifications'),('public.sms_envoyes'),('public.soignants'),('public.tokens_push'),('public.types_comptes_auth'),('storage.buckets'),('storage.objects')),
fonctions_cibles(signature) AS (VALUES ('auth.jwt()'),('auth.uid()'),('extensions.digest(bytea,text)'),('extensions.digest(text,text)'),('extensions.gen_random_bytes(integer)'),('extensions.grant_pg_cron_access()'),('extensions.grant_pg_graphql_access()'),('extensions.grant_pg_net_access()'),('extensions.pgrst_ddl_watch()'),('extensions.pgrst_drop_watch()'),('extensions.set_graphql_placeholder()'),('extensions.uuid_generate_v4()'),('pg_catalog.gen_random_uuid()'),('private.fn_anonymisation_compte_confirmee(uuid,text)'),('private.fn_forcer_compte_test_prelaunch()'),('public.dec_bloquer_modification_audit()'),('public.dec_bloquer_suppression_audit()'),('public.dec_detecter_secteur_public_etablissement()'),('public.dec_proteger_journaux_audit()'),('public.dec_valider_couleur_theme()'),('public.est_admin()'),('public.est_admin_valide()'),('public.fn_a_permission_etablissement(text,uuid)'),('public.fn_auth_user_deleted_cleanup_soignant()'),('public.fn_auto_code_parrainage_etab()'),('public.fn_auto_valider_etablissement_siret()'),('public.fn_classifier_canal(text,text,text,text)'),('public.fn_compte_auth_actif()'),('public.fn_ecrire_audit_safe(uuid,text,text,text,uuid,text,jsonb,inet,text)'),('public.fn_enforce_etablissement_rbac_trigger()'),('public.fn_generer_code_parrainage_etab()'),('public.fn_invalider_provenance_rib_etablissement()'),('public.fn_invalider_verifications_etablissement()'),('public.fn_mirror_teleportation_alerte_systeme()'),('public.fn_normaliser_nom(text)'),('public.fn_protect_etablissement_commercial()'),('public.fn_protect_etablissement_storage_paths()'),('public.fn_protect_famille_compte_membre_etablissement()'),('public.fn_role_etablissement_courant(uuid)'),('public.fn_signer_contrat_service(text,text,text,text,text)'),('public.fn_supprimer_mon_compte_etablissement()'),('public.fn_trg_anonymiser_notations_suppression()'),('public.fn_trg_classifier_acquisition()'),('public.fn_trg_defaut_mode_paiement_secteur()'),('public.fn_trg_init_preferences_notifications()'),('public.fn_trg_pn_updated_at()'),('public.fn_trg_tripwire_premier_mandat_sepa()'),('public.fn_verifier_coherence_publication()'),('public.fn_versionner_verifications_etablissement()'),('public.mon_etablissement_id()'),('storage.protect_delete()'),('storage.update_updated_at_column()')),
fonctions_draft(signature) AS (VALUES ('public.fn_proteger_preparation_contrat_service()'),('private.fn_purger_preparations_contrat_non_signees(uuid)'),('private.fn_purger_preparations_apres_anonymisation()'),('public.fn_donnees_contrat_service(uuid)'),('public.fn_valeur_contrat_service(text)'),('public.fn_texte_contrat_service_v11(jsonb)'),('public.fn_preparer_contrat_service_v11()'),('public.fn_signer_contrat_service_v11(uuid,text,text)'),('public.fn_lire_contrat_service_signe()'),('public.fn_proteger_signature_contrat_preparee()'),('public.fn_proteger_image_signature_service()')),
tables_meta AS (SELECT x.nom,c.oid,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl,pg_get_userbyid(c.relowner) AS owner FROM tables_cibles x LEFT JOIN pg_class c ON c.oid=to_regclass(x.nom)),
collisions AS (SELECT 'auth.users' AS objet,count(*) AS nombre FROM auth.users WHERE id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.etablissements' AS objet,count(*) AS nombre FROM public.etablissements WHERE id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.soignants' AS objet,count(*) AS nombre FROM public.soignants WHERE id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.membres_etablissement' AS objet,count(*) AS nombre FROM public.membres_etablissement WHERE user_id=ANY((SELECT ids FROM fixture)::uuid[]) OR etablissement_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.contrats_service_signatures' AS objet,count(*) AS nombre FROM public.contrats_service_signatures WHERE etablissement_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.preferences_notifications' AS objet,count(*) AS nombre FROM public.preferences_notifications WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.notifications' AS objet,count(*) AS nombre FROM public.notifications WHERE destinataire_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.email_queue' AS objet,count(*) AS nombre FROM public.email_queue WHERE destinataire_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.journaux_audit' AS objet,count(*) AS nombre FROM public.journaux_audit WHERE acteur_id=ANY((SELECT ids FROM fixture)::uuid[]) OR id_ressource=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'private.suppressions_compte_confirmees' AS objet,count(*) AS nombre FROM private.suppressions_compte_confirmees WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'private.suppression_etablissement_context' AS objet,count(*) AS nombre FROM private.suppression_etablissement_context WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.admins_groupe_sante' AS objet,count(*) AS nombre FROM public.admins_groupe_sante WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.tokens_push' AS objet,count(*) AS nombre FROM public.tokens_push WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.messages_chat' AS objet,count(*) AS nombre FROM public.messages_chat WHERE auteur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.messages_mission' AS objet,count(*) AS nombre FROM public.messages_mission WHERE auteur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.messages_litige' AS objet,count(*) AS nombre FROM public.messages_litige WHERE auteur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.evaluations' AS objet,count(*) AS nombre FROM public.evaluations WHERE evaluateur_id=ANY((SELECT ids FROM fixture)::uuid[]) OR evalue_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.exclusions' AS objet,count(*) AS nombre FROM public.exclusions WHERE exclu_par=ANY((SELECT ids FROM fixture)::uuid[]) OR exclu_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.sms_envoyes' AS objet,count(*) AS nombre FROM public.sms_envoyes WHERE destinataire_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.calendar_connections' AS objet,count(*) AS nombre FROM public.calendar_connections WHERE utilisateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.notations_missions' AS objet,count(*) AS nombre FROM public.notations_missions WHERE notateur_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.partages_rib' AS objet,count(*) AS nombre FROM public.partages_rib WHERE etablissement_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.contrats_mission' AS objet,count(*) AS nombre FROM public.contrats_mission WHERE etablissement_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.api_keys' AS objet,count(*) AS nombre FROM public.api_keys WHERE etablissement_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'public.types_comptes_auth' AS objet,count(*) AS nombre FROM public.types_comptes_auth WHERE user_id=ANY((SELECT ids FROM fixture)::uuid[])
 UNION ALL SELECT 'storage.objects',count(*) FROM storage.objects WHERE split_part(name,'/',1)=ANY((SELECT ids::text[] FROM fixture)::text[])),
empreintes_tables AS (
 SELECT c.nom,
 md5(jsonb_build_object('kind',c.relkind,'owner',c.owner,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,
 'columns',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum),'[]') FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated) ORDER BY k.conname),'[]') FROM pg_constraint k WHERE k.conrelid=c.oid),
 'indexes',(SELECT COALESCE(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text),'[]') FROM pg_index i WHERE i.indrelid=c.oid),
 'policies',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.policyname,'cmd',p.cmd,'roles',p.roles,'permissive',p.permissive,'qual',p.qual,'check',p.with_check) ORDER BY p.policyname),'[]') FROM pg_policies p WHERE format('%I.%I',p.schemaname,p.tablename)=c.nom),
 'triggers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),
 'rules',(SELECT COALESCE(jsonb_agg(pg_get_ruledef(r.oid,true) ORDER BY r.rulename),'[]') FROM pg_rewrite r WHERE r.ev_class=c.oid AND r.rulename<>'_RETURN'))::text) AS empreinte FROM tables_meta c
)
SELECT
 (SELECT jsonb_object_agg(nom,empreinte ORDER BY nom) FROM empreintes_tables) AS tables_md5,
 (SELECT jsonb_object_agg(x.signature,CASE WHEN p.oid IS NULL THEN NULL ELSE md5(jsonb_build_object('definition',pg_get_functiondef(p.oid),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner),'leakproof',p.proleakproof)::text) END ORDER BY x.signature) FROM fonctions_cibles x LEFT JOIN pg_proc p ON p.oid=to_regprocedure(x.signature)) AS fonctions_md5,
 (SELECT jsonb_object_agg(objet,nombre ORDER BY objet) FROM collisions) AS collisions,
 (SELECT count(*) FROM cron.job WHERE active) AS crons_actifs,
 (SELECT count(*) FROM pg_trigger WHERE tgrelid='auth.users'::regclass AND NOT tgisinternal AND tgenabled<>'D' AND (tgtype::integer & (4|16))<>0) AS triggers_auth_insert_update,
 (SELECT count(*) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgenabled<>'D' AND (t.tgtype::integer & 1)=0 AND t.tgrelid IN(SELECT oid FROM cascades)) AS triggers_statement_cascade,
 (SELECT count(*) FROM pg_constraint WHERE contype='f' AND NOT convalidated AND confrelid IN(SELECT oid FROM cascades)) AS foreign_keys_unvalidated,
 (SELECT count(*) FROM pg_attrdef d JOIN tables_meta c ON c.oid=d.adrelid WHERE pg_get_expr(d.adbin,d.adrelid)~*'(nextval|setval)[[:space:]]*[(]') AS defaults_sequence,
 (SELECT md5(COALESCE(jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'owner',pg_get_userbyid(evtowner),'enabled',evtenabled,'tags',evttags,'function',evtfoid::regprocedure::text) ORDER BY evtname),'[]')::text) FROM pg_event_trigger WHERE evtenabled<>'D') AS event_triggers_md5,
 (SELECT md5(COALESCE(jsonb_agg(jsonb_build_object('role',rolname,'superuser',rolsuper,'bypassrls',rolbypassrls,'inherit',rolinherit) ORDER BY rolname),'[]')::text) FROM pg_roles WHERE rolname IN('postgres','supabase_admin','supabase_auth_admin','service_role','authenticated','anon')) AS roles_md5,
 (SELECT count(*) FROM storage.buckets WHERE id IN('jolene-documents','copies-bulletins-paie') AND public IS FALSE) AS buckets_prives,
 (to_regclass('storage.prefixes') IS NULL) AS storage_prefixes_absent,
 (SELECT jsonb_object_agg(signature,to_regprocedure(signature) IS NULL ORDER BY signature) FROM fonctions_draft) AS fonctions_draft_absentes,
 (to_regclass('public.contrats_service_preparations') IS NULL) AS table_draft_absente,
 (SELECT NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.contrats_service_signatures'::regclass AND attname='preparation_id' AND NOT attisdropped)) AS colonne_draft_absente,
 (SELECT count(*) FROM pg_trigger WHERE tgname IN('trg_preparation_contrat_service_immuable','trg_purger_preparations_apres_anonymisation','trg_signature_contrat_preparee_immuable','trg_image_signature_service_immuable')) AS triggers_draft,
 (SELECT count(*) FROM private.security_definer_inventory WHERE signature IN('fn_preparer_contrat_service_v11()','fn_signer_contrat_service_v11(uuid,text,text)','fn_lire_contrat_service_signe()')) AS inventaire_draft,
 (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260929215439') AS migration_draft,
 (session_user='postgres' AND current_user='postgres') AS session_postgres;
